<?php $this->layout('default'); use Moves\Services\CmsContent; use Moves\Support\CmsView as V; $rows = CmsContent::categories(); $edit = null; foreach ($rows as $r) { if ((string) $r['id'] === V::queryString('editar')) { $edit = $r; } }
$this->start('actions'); ?><a class="cms-btn" href="/conteudos">Voltar</a><?php $this->stop(); ?>
<div class="cms-form-list"><form class="cms-card" method="post" action="/acao/category-save"><header class="cms-card-head"><div><h2><?= $edit ? 'Editar categoria' : 'Cadastrar categoria' ?></h2><small>Organize os conteúdos do site.</small></div><?= V::icon('list') ?></header><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?: '' ?>"><?= V::field('Nome', 'title', $edit['title'] ?? '', ['required' => true]) ?><?= V::field('Descrição', 'description', $edit['description'] ?? '', ['type' => 'textarea', 'rows' => 3]) ?><div class="cms-form-end"><button class="cms-btn-primary">Salvar categoria</button></div></form>
<section class="cms-card"><header class="cms-card-head"><div><h2>Categorias cadastradas</h2><small>Usadas em artigos e notícias.</small></div><b class="cms-count"><?= count($rows) ?></b></header><?php if ($rows === []): ?><?= V::empty('Nenhuma categoria cadastrada.') ?><?php endif; foreach ($rows as $row): ?><div class="cms-row"><div><strong><?= V::e($row['title']) ?></strong><br><small><?= (int) $row['posts_count'] ?> conteúdo(s)</small></div><div class="cms-td-actions"><?= V::iconLink('?editar=' . (int) $row['id'], 'Editar') ?><?= V::iconAction('category-delete', 'Excluir', ['id' => $row['id']], 'Excluir esta categoria?') ?></div></div><?php endforeach; ?></section></div>
